from dna_function import count_nucleotide, GC_content
from Bio import SeqIO

for record in SeqIO.parse("EGFR.fasta", "fasta"):
    id = record.id
    length = len(str(record.seq))
    sequence = str(record.seq)
    print (id,length,sequence)

TP53_dict = {"Gene":"TP53" , "Accession":"NM_000546.6" , "Length":"2512" , "Sequence":""}
MYC_dict = {"Gene":"MYC" , "Accession":"NM_002467.6" , "Length":"3721" , "Sequence":""}
Bcl2_dict = {"Gene":"Bcl2" , "Accession":"NM_000633.3" , "Length":"6881" , "Sequence":""}
ABCB1_dict = {"Gene":"ABCB1" , "Accession":"NM_000927.5" , "Length":"5534" , "Sequence":""}
EGFR_dict = {"Gene":"EGFR" , "Accession":"NM_005228.5" , "Length":"9905" , "Sequence":""}

import pandas as pd
gene_dict = [TP53_dict,MYC_dict,Bcl2_dict,ABCB1_dict,EGFR_dict]
df = pd.DataFrame(gene_dict)

GC = df["Sequence"].apply(GC_content)
Nucleotide = df["Sequence"].apply(count_nucleotide)

df["GC_%"] = GC
df["Nucleotides"] = Nucleotide

df["A"] = df["Nucleotides"].apply(lambda x : x["A"])
df["T"] = df["Nucleotides"].apply(lambda x : x["T"])
df["G"] = df["Nucleotides"].apply(lambda x : x["G"])
df["C"] = df["Nucleotides"].apply(lambda x : x["C"])
print (df)